// Применение: заголовок позиции должен совпасть точно.
// Промах роняет сборку — иначе опечатка молча ничего не сделает.
export function applyDetails(sections: Section[], tables: DetailTable[]): void {
  const missing: string[] = [];
  for (const table of tables) {
    for (const [sectionId, rows] of Object.entries(table)) {
      const section = sections.find((s) => s.id === sectionId);
      if (!section) { missing.push(`раздел ${sectionId}`); continue; }
      for (const [title, text] of Object.entries(rows)) {
        const entry = section.entries.find((e) => e.title === title);
        if (!entry) { missing.push(`${sectionId} :: «${title}»`); continue; }
        entry.detail = text;
      }
    }
  }
  if (missing.length) {
    throw new Error(
      "Механизм не привязан — заголовок не найден (" + missing.length + "):\n  " +
      missing.slice(0, 20).join("\n  "),
    );
  }
}

